  2268  static int coolkey_init(sc_card_t *card)
  2269  {
  2270          int r;
  2271          unsigned long flags;
  2272          unsigned long ext_flags;
  2273          coolkey_private_data_t * priv;
  2274
  2275          SC_FUNC_CALLED(card->ctx, SC_LOG_DEBUG_VERBOSE);
  2276
  2277          r = coolkey_initialize(card);
  2278          if (r < 0) {
  2279                  LOG_FUNC_RETURN(card->ctx, SC_ERROR_INVALID_CARD);
  2280          }
  2281
  2282          card->type = SC_CARD_TYPE_COOLKEY_GENERIC;
  2283
  2284          /* set Token Major/minor version */
  2285          flags = SC_ALGORITHM_RSA_RAW;
  2286
  2287          _sc_card_add_rsa_alg(card, 1024, flags, 0); /* mandatory */
  2288          _sc_card_add_rsa_alg(card, 2048, flags, 0); /* optional */
  2289          _sc_card_add_rsa_alg(card, 3072, flags, 0); /* optional */
  2290
  2291          flags = SC_ALGORITHM_ECDSA_RAW | SC_ALGORITHM_ECDH_CDH_RAW | SC_ALGORITHM_ECDSA_HASH_NONE;
  2292          ext_flags = SC_ALGORITHM_EXT_EC_NAMEDCURVE | SC_ALGORITHM_EXT_EC_UNCOMPRESES;
  2293
  2294          _sc_card_add_ec_alg(card, 256, flags, ext_flags, NULL);
  2295          _sc_card_add_ec_alg(card, 384, flags, ext_flags, NULL);
  2296          _sc_card_add_ec_alg(card, 521, flags, ext_flags, NULL);
  2297
  2298
  2299          priv = COOLKEY_DATA(card);
  2300          if (priv->pin_count != 0) {
  2301                  card->caps |= SC_CARD_CAP_ISO7816_PIN_INFO;
  2302          }
  2303
  2304          LOG_FUNC_RETURN(card->ctx, SC_SUCCESS);
  2305  }
